package com.mandu.liquiddialer
import androidx.compose.ui.test.*
import androidx.compose.ui.semantics.getOrNull
import androidx.compose.ui.semantics.SemanticsProperties
import androidx.datastore.preferences.core.edit
import com.mandu.liquiddialer.data.*
import com.mandu.liquiddialer.ui.*
import kotlinx.coroutines.runBlocking
import org.junit.*
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.*
@RunWith(RobolectricTestRunner::class) @Config(sdk=[34],qualifiers="w360dp-h800dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
class SettingsSectionSearchUiTest:OrganizedSettingsFixture(){
 @Before fun reset(){runBlocking{ctx.ldStore.edit{it[K.settingsSectionSearch]=false;it[K.compactSettingsTools]=false;it[K.alphabeticalSettingsTools]=false;it[K.settingsToolSearch]=false}};await{LdApp.settings.value.let{!it.settingsSectionSearch&&!it.compactSettingsTools&&!it.alphabeticalSettingsTools&&!it.settingsToolSearch}}}
 private fun enable(){runBlocking{ctx.ldStore.edit{it[K.settingsSectionSearch]=true}};await{LdApp.settings.value.settingsSectionSearch};settle()}
 private fun query(q:String){rule.onNode(hasSetTextAction() and hasAnyAncestor(hasTestTag("settings_section_query")),true).performTextReplacement(q);settle()}
 private fun rows()=rule.onAllNodes(SemanticsMatcher("tool row"){it.config.getOrNull(SemanticsProperties.TestTag)?.startsWith("settings_tool_")==true},true).fetchSemanticsNodes().map{it.config[SemanticsProperties.TestTag]}
 @Test fun defaultOffPreservesAllSections(){assertFalse(LdSettings().settingsSectionSearch);start();for(section in listOf("live","notes","calculators")){show("settingstools:"+section);rule.onNodeWithTag("settings_section_query",true).assertDoesNotExist();assertEquals(settingsSectionTools(section,false).map{"settings_tool_"+it.route},rows())}}
 @Test fun sectionScopeCaseWhitespaceMultiwordAndDescription(){assertEquals(listOf("ivrmenus"),settingsSectionTools("live",false,"  SAVED   DIGIT ").map{it.route});assertTrue(settingsSectionTools("notes",false,"digit").isEmpty());assertTrue(settingsSectionTools("live",false,"calculator").isEmpty());assertEquals(settingsSectionTools("notes",false),settingsSectionTools("notes",false,"  "));assertTrue(settingsSectionTools("unknown",false,"a").isEmpty());val before=ORGANIZED_TOOLS.toList();settingsSectionTools("calculators",true,"calculator");assertEquals(before,ORGANIZED_TOOLS)}
 @Test fun actualFilterCountClearAndAllRoutesNoSideEffect(){start();enable();val before=LdApp.settings.value;for(t in ORGANIZED_TOOLS){show("settingstools:"+t.section);query(t.title);assertTrue("settings_tool_"+t.route in rows());assertTrue(rows().all{tag->ORGANIZED_TOOLS.any{it.section==t.section&&"settings_tool_"+it.route==tag}});rule.onNodeWithTag("settings_section_count",true).assertTextEquals("Tools: ${settingsSectionTools(t.section,false,t.title).size}");tapTag("settings_tool_"+t.route);assertEquals(t.route,opened.last())};assertEquals(before,LdApp.settings.value);assertNull(rule.activity.state.pendingCall)}
 @Test fun emptyStateAndClearRestore(){start();enable();show("settingstools:notes");query("zzzz-no-match");assertTrue(rows().isEmpty());text("No tool found in this section").assertExists();rule.onNodeWithTag("settings_section_count",true).assertTextEquals("Tools: 0");tapTag("settings_section_clear");assertEquals(settingsSectionTools("notes",false).map{"settings_tool_"+it.route},rows());text("No tool found in this section").assertDoesNotExist();rule.onNodeWithTag("settings_section_count",true).assertDoesNotExist()}
 @Test fun switchReversibleOnePreferenceAndNoStaleQuery(){start();show("settingshub:tools");val before=LdApp.settings.value;tapTag("settings_section_search_switch");await{LdApp.settings.value.settingsSectionSearch};assertEquals(before.copy(settingsSectionSearch=true),LdApp.settings.value);show("settingstools:live");query("IVR");show("settingstools:notes");assertEquals(settingsSectionTools("notes",false).map{"settings_tool_"+it.route},rows());show("settingshub:tools");tapTag("settings_section_search_switch");await{!LdApp.settings.value.settingsSectionSearch};assertEquals(before,LdApp.settings.value);show("settingstools:live");rule.onNodeWithTag("settings_section_query",true).assertDoesNotExist();assertEquals(settingsSectionTools("live",false).map{"settings_tool_"+it.route},rows())}
 @Test fun alphabeticalAndCompactIndependent(){start();enable();runBlocking{ctx.ldStore.edit{it[K.alphabeticalSettingsTools]=true;it[K.compactSettingsTools]=true}};await{LdApp.settings.value.alphabeticalSettingsTools&&LdApp.settings.value.compactSettingsTools};show("settingstools:calculators");query("calculator");assertEquals(settingsSectionTools("calculators",true,"calculator").map{"settings_tool_"+it.route},rows());for(t in settingsSectionTools("calculators",true,"calculator"))rule.onNodeWithText(t.detail,false,true).assertDoesNotExist();rule.onNodeWithTag("settings_tools_az_label",true).assertExists()}
 @Test fun queryCappedAndOriginalSearchFinderClassicUnaffected(){start();val global=searchSettingsTools("IVR");enable();show("settingstools:live");query("x".repeat(130));rule.onNode(hasSetTextAction() and hasAnyAncestor(hasTestTag("settings_section_query")),true).assertTextEquals("x".repeat(100));assertEquals(global,searchSettingsTools("IVR"));assertTrue(SettingsFinder.search("Search inside call-tool sections").any{it.id=="settings-section-search"&&it.route=="settingshub:tools"});show("settingshub:classic");text(SETTINGS_GROUPS.first().summary).assertExists();show("settings:recents");text("Home pe favourite contacts dikhao/chhupao").assertExists()}
 @Test fun dayAndOffPixels(){start();enable();show("settingstools:notes");query("call");shot("SET513-day-results");query("no-match-zz");shot("SET513-day-empty");show("settingshub:tools");tapTag("settings_section_search_switch");await{!LdApp.settings.value.settingsSectionSearch};rule.mainClock.autoAdvance=true;rule.onNodeWithTag("settings_section_search_switch",true).performScrollTo();settle();shot("SET513-off");show("settingstools:notes");shot("SET513-off-notes")}
}
@RunWith(RobolectricTestRunner::class) @Config(sdk=[34],qualifiers="w320dp-h640dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
class SettingsSectionSearchNightUiTest:OrganizedSettingsFixture(){
 @Test fun nightLargeSearchAndCompact(){start(night=true);runBlocking{ctx.ldStore.edit{it[K.settingsSectionSearch]=true;it[K.compactSettingsTools]=true}};await{LdApp.settings.value.settingsSectionSearch&&LdApp.settings.value.compactSettingsTools};show("settingstools:calculators");rule.onNode(hasSetTextAction() and hasAnyAncestor(hasTestTag("settings_section_query")),true).performTextReplacement("calculator");settle();shot("SET513-night");rule.mainClock.autoAdvance=true;rule.onNodeWithTag("settings_tool_installmentpreview",true).performScrollTo();settle();shot("SET513-night-result");rule.onNodeWithText("Calculator installment preview",false,true).assertIsDisplayed();assertNull(rule.activity.state.pendingCall)}
}
